"""
    The number of samples in an exponentially growing 1D quadrature rule of
    a given level.

    Parameters
    ----------
    level : integer
       The level of the quadrature rule

    Return
    ------
    num_samples_1d : integer
        The number of samples in the quadrature rule
    """
def exponential_growth(level: Any, constant: Any = 1) -> object {
    if (level == 0) {
        return 1;
    }
    return ((constant * (2 ** (level + 1))) - 1);
}

"""
    converts base 26 number-char into decimal
    :param x:
    :return:
    """
def _x2n(x: Any) -> object {
    numerals = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    b = 26;
    n = 0;
    for (i, l) in enumerate(reversed(x)) {
        n += (numerals.index(l) + 1) * (b ** i);
    }
    return n;
}

